use super::*;
#[test]
fn genuine_source_loan_control_alias_return_and_clock_clear_post_distinct_actual_work(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let stock=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let quantum=RetainedCloneGrant{maximum_items:1,..stock};
 let mut caller=semio_framework_job_testing_caller::OriginalJobFixtureCaller::admit(OperationId(row["operation"].as_u64().unwrap()),Generation(row["generation"].as_u64().unwrap()),stock,||Some(1),u64::MAX,s["fuel"].as_u64().unwrap());let mut pending=None;caller.turn(quantum,|cx|cx.original_source_parent()?.admit_loan(&mut pending,cx)).unwrap();let mut loan=pending.unwrap();let clock=loan.original_clock_source().unwrap();let identity=loan.source_identity().unwrap();
 let units=caller.turn(RetainedCloneGrant{maximum_items:0,..quantum},|cx|{let fuel=cx.fuel_remaining();let step=loan.close_step(cx.original_source_parent()?,cx)?;assert_eq!(step.progress(),Default::default());Ok(fuel-cx.fuel_remaining())}).unwrap();assert_eq!(units,row["deniedWork"].as_u64().unwrap());caller.turn(quantum,|cx|loan.validate_context(cx)).unwrap();assert_eq!(loan.source_identity().unwrap(),identity);assert_eq!(loan.original_clock_source().unwrap().0,clock.0);
 let mut work=Vec::new();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if loan.terminal_is_empty(){break;}let units=caller.turn(quantum,|cx|{let fuel=cx.fuel_remaining();let step=loan.close_step(cx.original_source_parent()?,cx)?;assert_eq!(step.progress().copied_bytes,0);assert_eq!(step.progress().retained_capacity_bytes,0);assert_eq!(step.progress().released_bytes,0);Ok(fuel-cx.fuel_remaining())}).unwrap();work.push(units);if let Ok(current)=loan.original_clock_source(){assert_eq!((current.0,current.2),(clock.0,clock.2));assert!(std::ptr::fn_addr_eq(current.1,clock.1));}}
 assert!(loan.terminal_is_empty());assert!(loan.original_clock_source().is_err());assert_eq!(serde_json::to_value(work).unwrap(),row["work"]);let units=caller.turn(quantum,|cx|{let fuel=cx.fuel_remaining();loan.close_step(cx.original_source_parent()?,cx)?;Ok(fuel-cx.fuel_remaining())}).unwrap();assert_eq!(units,row["cachedWork"].as_u64().unwrap());drop(loan);caller.retire(stock);
}
